/** Must stay in sync with `CANVAS_RCE_HEIGHT_MESSAGE` in `.vitepress/theme/canvas-rce.ts`. */
const MESSAGE_TYPE = "pantoken:canvas-rce:height";

function contentHeight(): number {
  const { body, documentElement } = document;
  const style = getComputedStyle(body);
  const margins = Number.parseFloat(style.marginTop) + Number.parseFloat(style.marginBottom);
  // `documentElement`'s box is content-sized (so it shrinks again), but body margins collapse out of
  // it — add them back rather than using `scrollHeight`, which can never report less than the iframe.
  return Math.ceil(
